const ASSET = 'assets/bliu-lookbook.png';
const products = [
  {id:'midnight-anarkali',name:'Zareen Handcrafted Tissue Silk Anarkali',line:'BLIU Luxe',category:'Anarkalis',fabric:'Tissue silk',color:'Antique Champagne',price:148500,position:1,tag:'ATELIER EDITION'},
  {id:'obsidian-drape',name:'Obsidian Zardozi Anarkali',line:'BLIU Luxe',category:'Anarkalis',fabric:'Velvet silk',color:'Obsidian',price:163000,position:1,tag:'HAND FINISHED'},
  {id:'gold-thread',name:'Zareen Banarasi Dupatta Set',line:'BLIU Luxe',category:'Embroidered suits',fabric:'Tissue silk',color:'Antique Gold',price:148500,position:1,tag:'COUTURE PIECE'},
  {id:'organza-trench',name:'Nocturne Drape Set',line:'BLIU Luxe',category:'Lehengas',fabric:'Silk organza',color:'Midnight Black',price:128000,position:2,tag:'LIMITED ATELIER'},
  {id:'sage-kurta',name:'Gulbahaar Hand-Embroidered Chanderi Kurta Set',line:'BLIU Essentials',category:'Kurtas & tunics',fabric:'Chanderi silk',color:'Ivory and marigold',price:14800,position:3,tag:'BESTSELLER'},
  {id:'ivory-coord',name:'Aria Ivory Raw Silk Peplum Kurta & Dhoti',line:'BLIU Essentials',category:'Co-ord sets',fabric:'Raw silk',color:'Ivory',price:18500,position:4,tag:'PURE MULBERRY SILK'},
  {id:'studio-kurta',name:'Nazakat Tissue Silk Anarkali',line:'BLIU Essentials',category:'Anarkalis',fabric:'Tissue silk',color:'Ivory',price:24900,position:4,tag:'LIGHT FESTIVE'},
  {id:'modern-dupatta',name:'Noor-e-Bahaar Kalidar Suit with Organza Dupatta',line:'BLIU Essentials',category:'Festive suits',fabric:'Maheshwari silk and organza',color:'Ivory',price:22000,position:4,tag:'LIGHT FESTIVE'},
  {id:'mehr-coord',name:'Mehr Marigold Banarasi Co-ord Set',line:'BLIU Essentials',category:'Co-ord sets',fabric:'Banarasi silk',color:'Marigold',price:16200,position:3,tag:'SLOW HANDLOOM'},
  {id:'awadhi-angrakha',name:'Awadhi Chikankari Georgette Angrakha',line:'BLIU Essentials',category:'Kurtas & tunics',fabric:'Georgette',color:'Ivory',price:19800,position:4,tag:'ARTISAN DETAIL'},
  {id:'asymmetric-tunic',name:'Chanderi Asymmetric Tunic & Cigarette Pant',line:'BLIU Essentials',category:'Co-ord sets',fabric:'Chanderi katan',color:'Ivory',price:13400,position:3,tag:'DAY TO SOIRÉE'},
  {id:'sufiyan-coord',name:'Sufiyan Block-Print Silk Chanderi Co-ord',line:'BLIU Essentials',category:'Co-ord sets',fabric:'Block-print Chanderi',color:'Natural dye',price:15600,position:3,tag:'ARTISAN EDITION'}
];
const pageNames={home:'Home',shop:'Shop All',luxe:'BLIU Luxe',essential:'BLIU Essentials',product:'Product Detail',cart:'Shopping Bag',checkout:'Secure Checkout',confirmation:'Order Confirmation',signin:'Account Access',account:'My Account',contact:'Concierge & Contact',story:'Our Story',size:'Size Guide',faq:'Frequently Asked Questions',shipping:'Shipping & Returns',track:'Track Order',journal:'Lookbook & Style Journal',wishlist:'Wishlist',reviews:'Reviews & Testimonials'};
const formatPrice=n=>'₹'+Number(n).toLocaleString('en-IN');
const image=(position=1,alt='BLIU Indian fusion wear',extraClass='')=>`<span class="look-crop quadrant-${position} ${extraClass}" role="img" aria-label="${String(alt).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}" style="--image-url:url('${ASSET}')"></span>`;
const imgClass=(position)=>`look-crop quadrant-${position}`;
const waLink=(message='Hello BLIU Concierge, I would love help finding a piece.')=>`https://wa.me/?text=${encodeURIComponent(message)}`;
const categoryKey=name=>name;
function getRoute(){const p=new URLSearchParams(location.search);return {page:p.get('page')||'home',id:p.get('id')||products[0].id};}
function go(page,extra={}){const p=new URLSearchParams({page,...extra});location.href=`?${p.toString()}`;}
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function writeStore(key,value){localStorage.setItem(key,JSON.stringify(value))}
function getCart(){return readStore('bliu-cart',[])}
function getWishlist(){return readStore('bliu-wishlist',[])}
function productCard(p){return `<article class="product-card" data-product="${p.id}" data-line="${p.line}" data-category="${p.category}" data-fabric="${p.fabric}" data-color="${p.color}" data-craft="${p.tag.includes('HAND')?'Hand embroidery':'Handwoven'}" data-sizes="XS (34),S (36),M (38),L (40),XL (42),XXL (44)" data-price="${p.price}"><a class="product-picture" href="?page=product&id=${p.id}">${image(p.position,p.name)}<span class="product-badge">${p.tag}</span><span class="product-actions"><span>VIEW PIECE</span><span>↗</span></span></a><div class="product-info"><div><h3><a href="?page=product&id=${p.id}">${p.name}</a></h3><p>${p.line} · ${p.color}</p></div><span class="price">${formatPrice(p.price)}</span></div></article>`;}
function header(theme='essential'){const count=getCart().reduce((n,item)=>n+item.qty,0);return `<div class="announcement">COMPLIMENTARY PAN-INDIA EXPRESS DELIVERY & BESPOKE FITTINGS · HANDCRAFTED IN INDIA</div><header class="site-header"><button class="mobile-menu" aria-label="Open navigation" aria-expanded="false"><span></span><span></span></button><nav class="main-nav" aria-label="Main navigation"><a class="line-link ${theme==='essential'?'active':''}" href="?page=essential">BLIU ESSENTIALS</a><a class="line-link ${theme==='luxe'?'active':''}" href="?page=luxe">BLIU LUXE</a></nav><a class="brandmark" href="?page=home" aria-label="BLIU — Beauty Lies In You"><span>BLIU</span><small>BEAUTY LIES IN YOU</small></a><div class="header-actions"><a class="nav-account" href="${readStore('bliu-client',null)?'?page=account':'?page=signin'}">ACCOUNT</a><a class="nav-account" href="?page=wishlist">WISHLIST</a><a class="bag-trigger" href="?page=cart">BAG <b>${count}</b></a></div></header>`;}
function footer(){return `<footer class="site-footer"><div class="footer-top"><div class="footer-brand"><a class="brandmark" href="?page=home"><span>BLIU</span><small>BEAUTY LIES IN YOU</small></a><p>Indian craft, reimagined for the way you move. Two expressions, one point of view.</p><a class="btn small outline" href="?page=contact">CONTACT THE CONCIERGE ↗</a></div><div class="footer-col"><b>DISCOVER</b><a href="?page=luxe">BLIU Luxe</a><a href="?page=essential">BLIU Essentials</a><a href="?page=shop&line=BLIU%20Essentials">Shop Essentials</a><a href="?page=shop&line=BLIU%20Luxe">Shop Luxe</a></div><div class="footer-col"><b>CLIENT CARE</b><a href="?page=contact">Concierge</a><a href="?page=size">Size guide</a><a href="?page=shipping">Shipping & returns</a><a href="?page=track">Track order</a><a href="?page=faq">FAQs</a></div><div class="footer-col"><b>THE STUDIO</b><a href="?page=story">Our story</a><a href="?page=journal">Style journal</a><a href="?page=reviews">Client notes</a><a href="?page=account">Your account</a><a href="?page=wishlist">Wishlist</a></div></div><div class="footer-bottom"><span>© 2026 BLIU · INDIA</span><span>INDIAN & INDO-WESTERN WOMENSWEAR</span><span>INR · INDIA</span></div></footer>`;}
function pageHero(kicker,title,copy,pos=1,theme='luxe'){return `<section class="page-hero ${theme==='essential'?'essential-hero':''}">${image(pos,title.replace(/<[^>]+>/g,''))}<div class="page-hero-copy"><p class="eyebrow gold">${kicker}</p><h1>${title}</h1><p>${copy}</p></div></section>`;}
function home(){return `<section class="gateway-intro"><p class="eyebrow">HAUTE HANDLOOMS & CONTEMPORARY FORM</p><h1>BLIU</h1><p class="gateway-fullname">BEAUTY LIES IN YOU</p><p>Artisanal hand-loomed heritage, shaped into contemporary Indian and Indo-Western silhouettes. Choose your expression.</p></section><section class="line-choice gateway-choice"><div class="line-choice-grid"><a class="line-choice-card essentials-choice" href="?page=essential">${image(3,'BLIU Essentials breathable Chanderi outfit')}<span class="choice-label"><small>PRÊT & DAY HANDLOOMS · REALM I</small><strong>BLIU Essentials</strong><i>LUMINOUS SIMPLICITY · ENTER ESSENTIALS ↗</i></span></a><a class="line-choice-card lux-choice" href="?page=luxe">${image(1,'BLIU Luxe black and antique gold couture')}<span class="choice-label"><small>IMPERIAL COUTURE · REALM II</small><strong>BLIU Luxe</strong><i>NOCTURNE ATELIER · ENTER LUXE ↗</i></span></a></div></section><section class="gateway-story"><p class="eyebrow">A HOUSE OF TWO EXPRESSIONS</p><h2>Indian craft, made for <em>your point of view.</em></h2><p>A dialogue between royal handloom heritage and contemporary drape. BLIU brings together Chanderi, Banarasi, Chikankari and Zardozi traditions across everyday and occasion wear.</p></section>`;}
function collection(page){const isLuxe=page==='luxe';const line=isLuxe?'BLIU Luxe':'BLIU Essentials';const list=products.filter(p=>p.line===line);const cats=isLuxe?['Anarkalis','Lehengas','Ghararas','Embroidered suits']:['Kurtas & tunics','Co-ord sets','Anarkalis','Festive suits'];const intro=isLuxe?'Heirloom bridal and ceremonial silhouettes, crafted in rich silk, Zari and hand-finished embroidery.':'Contemporary silhouettes in breathable Chanderi silk, ivory Angarkhas and handloom co-ords, made for modern Indian days.';return `${pageHero(isLuxe?'IMPERIAL COUTURE · NOCTURNE ATELIER':'PRÊT & DAY HANDLOOMS · REALM I',isLuxe?'BLIU<br><em>Luxe.</em>':'BLIU<br><em>Essentials.</em>',intro,isLuxe?1:3,isLuxe?'luxe':'essential')}<section class="collection-scope-band"><span>${isLuxe?'BLIU LUXE ONLY · IMPERIAL COUTURE':'BLIU ESSENTIALS ONLY · PRÊT CAPSULE'}</span><a href="?page=shop&line=${encodeURIComponent(line)}">SHOP ALL ${isLuxe?'LUXE':'ESSENTIALS'} ↗</a></section><section class="category-section"><div class="section-title"><div><p class="eyebrow">CURATED SILHOUETTES · 01 ARCHETYPES</p><h2>${isLuxe?'The Nocturne Atelier':'Daytime Foundations'}</h2><p class="collection-scope">${isLuxe?'Four couture forms for evening and ceremony.':'Four core cuts for effortless grace.'}</p></div><div class="category-carousel-controls" aria-label="Scroll categories"><button type="button" class="category-scroll" data-category-scroll="-1" aria-label="Scroll categories left">←</button><button type="button" class="category-scroll" data-category-scroll="1" aria-label="Scroll categories right">→</button></div></div><div class="category-grid" role="region" aria-label="${line} categories" tabindex="0">${cats.map((c,i)=>`<a class="category-tile" href="?page=shop&line=${encodeURIComponent(line)}&category=${encodeURIComponent(categoryKey(c))}">${image(isLuxe?[1,2,1,2][i]:[3,4,3,4][i],`${line} ${c}`)}<span>${c}<i>EXPLORE ↗</i></span></a>`).join('')}</div></section><section class="section ${isLuxe?'dark-section':''}"><div class="section-title"><div><p class="eyebrow">ARCHIVAL INVENTORY</p><h2>${isLuxe?'Nocturne couture silhouettes':'All Essentials silhouettes'}</h2><p class="collection-scope">This edit contains ${line} garments only.</p></div><a class="underlink" href="?page=shop&line=${encodeURIComponent(line)}">SHOP ALL ${isLuxe?'LUXE':'ESSENTIALS'} ↗</a></div><div class="product-grid">${list.map(productCard).join('')}</div></section>`;}
function shop(){const p=new URLSearchParams(location.search),line=p.get('line')||'BLIU Essentials',list=products.filter(x=>x.line===line),isLuxe=line==='BLIU Luxe',category=p.get('category');return `<div class="page-heading shop-heading"><p class="eyebrow">${line.toUpperCase()} ONLY · COLLECTION ARCHIVE</p><h1>Shop all<br><em>${isLuxe?'Luxe.':'Essentials.'}</em></h1><p class="collection-scope">This page shows ${line} clothing only. Switch collections from the header.</p></div><div class="filterbar"><span id="result-count">${String(list.length).padStart(2,'0')} PIECES · ${line.toUpperCase()}</span><div class="filter-controls"><button class="filter-open" type="button" aria-expanded="false">FILTER + SORT <span>⌄</span></button><select id="sort-filter" aria-label="Sort products"><option value="featured">Curated</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option></select></div></div><div class="filter-drawer" id="filter-drawer" hidden><div class="filter-drawer-head"><strong>REFINE ${isLuxe?'LUXE':'ESSENTIALS'}</strong><button type="button" class="filter-close" aria-label="Close filters">×</button></div><div class="filter-drawer-fields"><label>Category / silhouette<select id="category-filter"><option value="all">All silhouettes</option>${[...new Set(list.map(x=>x.category))].map(c=>`<option ${c===category?'selected':''}>${c}</option>`).join('')}</select></label><label>Craft<select id="craft-filter"><option value="all">All craft</option><option>Hand embroidery</option><option>Handwoven</option></select></label><label>Fabric<select id="fabric-filter"><option value="all">All fabrics</option>${[...new Set(list.map(x=>x.fabric))].map(f=>`<option>${f}</option>`).join('')}</select></label><label>Indian size<select id="size-filter"><option value="all">All sizes</option>${['XS (34)','S (36)','M (38)','L (40)','XL (42)','XXL (44)'].map(s=>`<option>${s}</option>`).join('')}</select></label><label>Colour<select id="color-filter"><option value="all">All colours</option>${[...new Set(list.map(x=>x.color))].map(c=>`<option>${c}</option>`).join('')}</select></label></div><button type="button" class="btn filter-apply">VIEW ${line.toUpperCase()} PIECES</button></div><section class="catalog-section"><div class="product-grid" id="catalog-grid">${list.map(productCard).join('')}</div></section>`;}
function productDetail(id){const p=products.find(x=>x.id===id)||products[0];return `<div class="product-detail"><div><div class="gallery-main">${image(p.position,p.name,'gallery-full')}</div><div class="gallery-thumbs"><button class="gallery-thumb selected" type="button" aria-label="Full view of ${p.name}" data-position="${p.position}" data-view="full">${image(p.position,`Full view of ${p.name}`)}</button><button class="gallery-thumb" type="button" aria-label="Closer view of ${p.name}" data-position="${p.position}" data-view="close">${image(p.position,`Closer view of ${p.name}`,'gallery-zoom-close')}</button><button class="gallery-thumb" type="button" aria-label="Craft detail of ${p.name}" data-position="${p.position}" data-view="detail">${image(p.position,`Craft detail of ${p.name}`,'gallery-zoom-detail')}</button></div></div><div class="product-detail-copy"><p class="eyebrow gold">${p.line.toUpperCase()} · ${p.tag}</p><h1>${p.name}</h1><p class="detail-price">${formatPrice(p.price)} <span class="notice">Inclusive of all taxes</span></p><p class="detail-desc">A considered Indian silhouette with a modern point of view. Finished by hand in a limited run, with thoughtful details designed to live beyond one occasion.</p><span class="detail-label">COLOUR · ${p.color.toUpperCase()}</span><button class="color-swatch" aria-label="${p.color}" title="${p.color}"></button><span class="detail-label">SELECT SIZE · <a href="?page=size" class="underlink">SIZE GUIDE ↗</a></span><div class="size-options">${['XS','S','M','L','XL','XXL'].map((s,i)=>`<button class="size-option ${i===2?'selected':''}" data-size="${s}">${s}</button>`).join('')}</div><div class="detail-cta"><button class="btn" data-add="${p.id}">ADD TO BAG <span>↗</span></button><a class="btn outline" target="_blank" rel="noreferrer" href="${waLink(`Hello BLIU Concierge, I'm interested in the ${p.name}.`)}">ORDER ON WHATSAPP</a></div><p class="notice">Small-batch made in India. Need help with fit? Our concierge is a message away.</p><div class="product-accordions"><details open><summary>CRAFT & COMPOSITION</summary><p>${p.fabric}, selected for its drape and hand-feel. Made in India in a considered, limited run.</p></details><details><summary>SHIPPING & RETURNS</summary><p>Ready-to-wear pieces are prepared with care and dispatched in 3–5 business days. Contact our concierge for made-to-order timelines.</p></details><details><summary>FIT & SIZE</summary><p>Designed for a relaxed silhouette. For a personal fit recommendation, reach our WhatsApp concierge.</p></details></div></div></div>${craftDetails(p)}<section class="section"><div class="section-title"><div><p class="eyebrow">MORE TO DISCOVER</p><h2>Pieces with <em>a point of view.</em></h2></div><a class="underlink" href="?page=shop&line=${encodeURIComponent(p.line)}">SHOP ALL ↗</a></div><div class="product-grid">${products.filter(x=>x.id!==p.id&&x.line===p.line).slice(0,4).map(productCard).join('')}</div></section>`;}
function craftDetails(p){return `<section class="craft-detail-section"><div class="craft-detail-heading"><p class="eyebrow">TEXTILE DOCUMENTATION · CRAFT DETAILS</p><h2>Look closer at <em>the craft.</em></h2><p>Details, materials and hand-finished techniques behind this ${p.line} garment.</p></div><div class="craft-detail-grid"><article>${image(p.position,'Textile and weave detail of '+p.name,'craft-shot craft-weave')}<div><small>01 · THE WEAVE</small><h3>${p.fabric}</h3><p>Natural texture and a fluid hand-feel, selected for the silhouette.</p></div></article><article>${image(p.position,'Embroidery detail of '+p.name,'craft-shot craft-embroidery')}<div><small>02 · EMBROIDERY & CRAFT</small><h3>Hand-finished in India</h3><p>Artisan detail brings depth and a considered finish to every piece.</p></div></article><article>${image(p.position,'Border and drape detail of '+p.name,'craft-shot craft-border')}<div><small>03 · BORDER & DRAPE</small><h3>Made to move beautifully</h3><p>Thoughtful finishing and clean edges create an effortless drape.</p></div></article></div></section>`;}
function cartPage(){const cart=getCart();if(!cart.length)return `<div class="page-heading"><p class="eyebrow">YOUR SELECTION</p><h1>Shopping bag</h1></div><section class="two-column"><div class="empty-state"><h2>Your bag is taking it slow.</h2><p>Explore the BLIU Luxe and BLIU Essentials collections to find your piece.</p><a class="btn" href="?page=shop">CONTINUE DISCOVERING ↗</a></div><aside class="order-summary"><h2>Order summary</h2><div class="summary-line"><span>Subtotal</span><span>₹0</span></div><div class="summary-line"><span>Shipping</span><span>Calculated at checkout</span></div><p class="notice">A WhatsApp concierge can help with sizing and styling.</p></aside></section>`;let total=0;const rows=cart.map(item=>{const p=products.find(x=>x.id===item.id);if(!p)return '';total+=p.price*item.qty;return `<div class="cart-item">${image(p.position,p.name)}<div><h3>${p.name}</h3><p>${p.line} · SIZE ${item.size||'M'}</p><p>${formatPrice(p.price)}</p><div class="cart-qty"><button data-qty="${p.id}" data-delta="-1" aria-label="Decrease quantity">−</button><span>${item.qty}</span><button data-qty="${p.id}" data-delta="1" aria-label="Increase quantity">+</button></div><button class="remove-item" data-remove="${p.id}">REMOVE</button></div><span>${formatPrice(p.price*item.qty)}</span></div>`}).join('');return `<div class="page-heading"><p class="eyebrow">YOUR SELECTION</p><h1>Shopping bag</h1></div><section class="two-column"><div class="cart-list">${rows}<a class="underlink" href="?page=shop">← CONTINUE DISCOVERING</a></div><aside class="order-summary"><h2>Order summary</h2><div class="summary-line"><span>Subtotal</span><span>${formatPrice(total)}</span></div><div class="summary-line"><span>Shipping</span><span>Complimentary</span></div><div class="summary-line"><span>Taxes</span><span>Included</span></div><div class="summary-line summary-total"><span>TOTAL</span><span>${formatPrice(total)}</span></div><a class="btn" style="width:100%;margin-top:17px" href="?page=checkout">PROCEED TO CHECKOUT ↗</a><a class="btn outline" style="width:100%;margin-top:9px" target="_blank" rel="noreferrer" href="${waLink('Hello BLIU Concierge, I have a question about my shopping bag.')}">ASK ON WHATSAPP</a></aside></section>`;}
function checkout(){const cart=getCart();const total=cart.reduce((sum,item)=>{const p=products.find(x=>x.id===item.id);return sum+(p?p.price*item.qty:0)},0);if(sessionStorage.getItem('bliu-order-confirmed')==='yes')return `<div class="page-heading"><p class="eyebrow">THANK YOU</p><h1>Your order is with us.</h1></div><section class="two-column"><div class="empty-state"><h2>We’ll take it from here.</h2><p>Your demo order has been noted. In a live shop, you would receive a confirmation and tracking details here.</p><a class="btn" href="?page=home">BACK TO BLIU ↗</a></div><aside class="order-summary"><p class="eyebrow">ORDER REFERENCE</p><h2>BLIU-2026-001</h2><p class="notice">This is a preview flow. No payment was taken.</p></aside></section>`;return `<div class="page-heading"><p class="eyebrow">YOUR BLIU ORDER</p><h1>Secure checkout</h1></div><section class="two-column"><form class="form-panel" data-form="checkout"><h2>Delivery details</h2><div class="field-grid"><div class="field"><label>FIRST NAME</label><input required autocomplete="given-name"></div><div class="field"><label>LAST NAME</label><input required autocomplete="family-name"></div><div class="field full"><label>EMAIL</label><input type="email" required autocomplete="email"></div><div class="field full"><label>ADDRESS</label><input required autocomplete="street-address"></div><div class="field"><label>CITY</label><input required autocomplete="address-level2"></div><div class="field"><label>PIN CODE</label><input required inputmode="numeric" pattern="[0-9]{6}" autocomplete="postal-code"></div><div class="field full"><label>PHONE NUMBER</label><input required type="tel" autocomplete="tel" placeholder="+91"></div></div><h2>Payment method</h2><div class="option-list"><label class="option-row"><input type="radio" name="payment" value="upi" checked> UPI / QR payment</label><label class="option-row"><input type="radio" name="payment" value="card"> Credit or debit card</label><label class="option-row"><input type="radio" name="payment" value="cod"> Cash on delivery (where available)</label></div><p class="notice">Preview only: submitting this form does not send personal details or charge a payment method.</p><button class="btn" style="margin-top:18px">PLACE PREVIEW ORDER ↗</button></form><aside class="order-summary"><h2>Your order</h2>${cart.length?cart.map(i=>{const p=products.find(x=>x.id===i.id);return p?`<div class="summary-line"><span>${p.name} × ${i.qty}</span><span>${formatPrice(p.price*i.qty)}</span></div>`:''}).join(''):'<p class="notice">Your bag is empty. You can still preview the checkout flow.</p>'}<div class="summary-line"><span>Shipping</span><span>Complimentary</span></div><div class="summary-line summary-total"><span>TOTAL</span><span>${formatPrice(total)}</span></div><p class="notice">Need help before placing your order? <a class="underlink" href="${waLink('Hello BLIU Concierge, I need help with checkout.')}">MESSAGE CONCIERGE ↗</a></p></aside></section>`;}
function contact(){return `${pageHero('HERE WHEN YOU NEED US','Bespoke<br><em>concierge.</em>','Elevated, personal help for styling advice, order updates and thoughtful questions.',2,'luxe')}<section class="two-column"><div class="content-panel"><p class="eyebrow">PERSONAL ASSISTANCE</p><h2>Let’s find the right piece.</h2><p class="detail-desc">Our Mumbai-based concierge is here for sizing, styling, order updates and bespoke inquiries. A real conversation, at your pace.</p><a class="btn" href="${waLink('Hello BLIU Concierge, I would love styling and product advice.')}" target="_blank" rel="noreferrer">START WHATSAPP CHAT ↗</a><p class="notice">Concierge hours: 10 AM – 8 PM IST</p><p class="notice">For press and partnerships: <a href="mailto:concierge@bliuluxe.com">concierge@bliuluxe.com</a></p></div><div class="info-panel"><p class="eyebrow">THE ATELIER</p><h2>Mumbai, India</h2><p>Visits by prior appointment. Write to our concierge and we’ll help arrange a time.</p><h2 style="margin-top:29px">Frequent inquiries</h2><div class="faq-list"><details><summary>Bespoke sizing & fittings</summary><p>Our sizing process starts with a virtual consultation and a personal measurement guide. In-person fittings are available in select cities.</p></details><details><summary>International shipping</summary><p>We ship internationally using insured couriers. Ready-to-wear typically dispatches in 3–5 business days; bespoke pieces take longer.</p></details><details><summary>Private viewings</summary><p>Private viewings can be arranged through our WhatsApp concierge, subject to availability.</p></details></div></div></section>`;}
function story(){return `${pageHero('THE HOUSE OF BLIU','Rooted here.<br><em>Made for everywhere.</em>','A contemporary Indian wardrobe shaped by craft, movement and the confidence to make a look your own.',3,'essential')}<section class="editorial dark-editorial"><div class="editorial-image">${image(1,'Black silk Anarkali with antique gold hand embroidery')}</div><div class="editorial-copy"><p class="eyebrow gold">OUR POINT OF VIEW</p><h2>Tradition is<br><em>always becoming.</em></h2><p>BLIU began with a simple belief: Indian dress can hold its heritage and move freely into the present. We work with skilled makers to bring familiar techniques into new forms—without losing the human detail that makes each piece feel personal.</p><a class="underlink" href="?page=contact">MEET US AT THE ATELIER ↗</a></div></section><section class="section"><div class="section-title"><div><p class="eyebrow">WHAT GUIDES US</p><h2>Made with <em>meaning.</em></h2></div></div><div class="feature-ribbon" style="margin:0 -6%;background:#f0eee8;color:#25231f"><div><b>01</b><span>Indian craft and textile knowledge, carried forward with care.</span></div><div><b>02</b><span>Small, considered runs over excess and hurry.</span></div><div><b>03</b><span>Design for repeat wear, celebration and everything between.</span></div></div></section>`;}
function sizeGuide(){const rows=[['XS (34)','32–34 / 81–86','26–27 / 66–69','36–37 / 91–94'],['S (36)','35–36 / 89–91','28–29 / 71–74','38–39 / 97–99'],['M (38)','37–38 / 94–97','30–32 / 76–81','40–42 / 102–107'],['L (40)','39–41 / 99–104','33–35 / 84–89','43–45 / 109–114'],['XL (42)','42–44 / 107–112','36–38 / 91–97','46–48 / 117–122'],['XXL (44)','45–47 / 114–119','39–41 / 99–104','49–51 / 124–130']];return `<div class="page-heading"><p class="eyebrow">A GOOD FIT STARTS HERE · INDIAN STANDARD</p><h1>Size & fit guide</h1><p class="detail-desc">Garment fit reference in inches and centimetres. Indian numeric sizing is shown alongside each international size. For style-specific ease, check the product page or ask our concierge.</p></div><section class="two-column"><div class="content-panel"><h2>Indian women’s size matrix</h2><p class="notice">Body measurements · inches / centimetres · ready-to-wear reference</p><table class="size-table"><thead><tr><th>INDIA / SIZE</th><th>BUST<br>IN / CM</th><th>WAIST<br>IN / CM</th><th>HIP<br>IN / CM</th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map((v,i)=>`<td>${i===0?`<strong>${v}</strong>`:v}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="notice">If your measurements fall between sizes, choose the larger size for a comfortable drape. Readymade pieces include a concealed 2-inch alteration margin.</p></div><div class="content-panel"><h2>How to measure</h2><div class="measure-grid"><div class="measure-card"><b>01 · Bust</b><p>Measure around the fullest part of your bust, keeping the tape parallel to the floor.</p></div><div class="measure-card"><b>02 · Waist</b><p>Measure around your natural waist, without pulling the tape tight.</p></div><div class="measure-card"><b>03 · Hips</b><p>Measure around the fullest part of your hips with your feet together.</p></div></div><a class="btn" style="margin-top:20px" target="_blank" rel="noreferrer" href="${waLink('Hello BLIU Concierge, please help me choose a size.')}">ASK OUR CONCIERGE ↗</a></div></section>`;}
function faq(){const qs=[['Shipping & delivery','Ready-to-wear pieces are prepared and dispatched in 3–5 business days. International delivery times vary by destination.'],['Do you ship internationally?','Yes. International shipping is available with insured couriers. Duties and taxes depend on the destination.'],['What is your return policy?','Eligible ready-to-wear pieces may be returned within 7 days of delivery if unworn, unwashed and with original tags. Contact the concierge to start a request.'],['How do I choose a size?','Use our size guide for measurements, or send your usual fit preference to the concierge for a personal recommendation.'],['What payment methods are available?','A live checkout can support UPI, cards and other options based on your payment provider. The current website preview does not process payments.'],['Are pieces made to order?','Some BLIU Luxe pieces are produced in limited runs. Product pages will show made-to-order details and expected dispatch timing.']];return `<div class="page-heading"><p class="eyebrow">CLIENT CARE</p><h1>Frequently asked questions</h1><p class="detail-desc">The details, thoughtfully answered.</p></div><section class="faq-layout"><nav class="faq-cats"><a href="#shipping">SHIPPING & DELIVERY ↗</a><a href="#returns">RETURNS & EXCHANGES ↗</a><a href="#payment">PAYMENT ↗</a><a href="?page=size">SIZING ↗</a></nav><div class="faq-list">${qs.map(([q,a],i)=>`<details id="${['shipping','international','returns','sizing','payment','made-to-order'][i]}"><summary>${q}</summary><p>${a}</p></details>`).join('')}<div class="content-panel" style="margin-top:25px"><h2>Still have a question?</h2><a class="btn" target="_blank" rel="noreferrer" href="${waLink('Hello BLIU Concierge, I have a question.')}">CONTACT CONCIERGE ↗</a></div></div></section>`;}
function track(){return `<div class="page-heading"><p class="eyebrow">YOUR ORDER, IN VIEW</p><h1>Track your order</h1><p class="detail-desc">Enter your order reference to check its journey. The preview recognizes the sample reference BLIU-2026-001.</p></div><section class="two-column"><form class="form-panel" data-form="track"><h2>Order status lookup</h2><div class="field"><label>ORDER REFERENCE</label><input required name="order" placeholder="e.g. BLIU-2026-001"></div><button class="btn">LOOK UP ORDER ↗</button><div id="track-result" aria-live="polite"></div></form><div class="info-panel"><p class="eyebrow">NEED A HAND?</p><h2>We’re here to help.</h2><p>For a personal update, send your order reference to the concierge.</p><a class="btn outline" target="_blank" rel="noreferrer" href="${waLink('Hello BLIU Concierge, I would like an update on my order.')}">ASK ON WHATSAPP ↗</a></div></section>`;}
function journal(){const stories=[['A softer kind of occasion','How the BLIU Luxe line brings quiet drama to Indian occasion dressing.',1,'BLIU Luxe JOURNAL'],['Five ways to wear the drape','One modern drape, styled for a long lunch, late evening and all the way home.',2,'STYLE NOTES'],['The everyday Indian wardrobe','Meet the pieces in BLIU Essentials that make getting dressed feel effortless.',3,'ESSENTIAL JOURNAL']];return `${pageHero('THE BLIU JOURNAL','A wardrobe<br><em>in motion.</em>','Notes on craft, contemporary Indian dressing and making a look your own.',4,'essential')}<section class="section"><div class="section-title"><div><p class="eyebrow">LOOKBOOK & STYLE JOURNAL</p><h2>Stories to <em>live in.</em></h2></div></div><div class="journal-grid">${stories.map(([title,desc,pos,tag])=>`<article class="journal-card">${image(pos,title)}<p class="eyebrow">${tag}</p><h3>${title}</h3><p>${desc}</p><a class="underlink" href="?page=story">READ THE STORY ↗</a></article>`).join('')}</div></section><section class="editorial dark-editorial"><div class="editorial-image">${image(2,'Modern black draped sari')}</div><div class="editorial-copy"><p class="eyebrow gold">THE BLIU Luxe EDIT</p><h2>For the details<br><em>that stay with you.</em></h2><p>Explore form, texture and the quiet confidence of pieces made for a lasting impression.</p><a class="underlink" href="?page=luxe">DISCOVER BLIU Luxe ↗</a></div></section>`;}
function account(){const saved=getWishlist();const wishCards=saved.map(id=>products.find(p=>p.id===id)).filter(Boolean);return `<div class="page-heading"><p class="eyebrow">YOUR BLIU</p><h1>Wishlist & account</h1></div><section class="section" style="padding-top:20px"><div class="account-grid"><div class="content-panel"><p class="eyebrow">YOUR DETAILS</p><h2>Welcome to the house.</h2><p class="detail-desc">This local preview keeps your wishlist on this device. Account sign-in and order history connect when a store backend is added.</p><a class="btn outline" href="?page=track">TRACK AN ORDER ↗</a></div><div class="content-panel"><p class="eyebrow">RECENT ORDER</p><h2>BLIU-2026-001</h2><p>Preview order · Status: in preparation</p><a class="underlink" href="?page=track">VIEW ORDER STATUS ↗</a></div></div><div class="section-title" style="margin-top:52px"><div><p class="eyebrow">SAVED FOR LATER</p><h2>Your <em>wishlist.</em></h2></div></div>${wishCards.length?`<div class="product-grid">${wishCards.map(productCard).join('')}</div>`:`<div class="empty-state"><h2>Your wishlist is waiting.</h2><p>Save the pieces you love as you explore.</p><a class="btn" href="?page=shop">EXPLORE THE COLLECTION ↗</a></div>`}</section>`;}
function reviews(){const reviewsData=[['“The drape is incredible. It felt like it was made for my evening.”','Aarohi M.','BLIU Luxe · Mumbai',1],['“Finally, a kurta set I can wear from a studio day straight to dinner.”','Mira S.','BLIU Essentials · Bengaluru',3],['“The concierge helped me choose a size and the fit was spot on.”','Naina K.','BLIU Luxe · Delhi',4]];return `<div class="page-heading"><p class="eyebrow">NOTES FROM THE BLIU COMMUNITY</p><h1>Worn & loved.</h1><p class="detail-desc">A few words from the people who bring these pieces to life.</p></div><section class="section" style="padding-top:20px"><div class="review-grid">${reviewsData.map(([quote,name,meta,pos])=>`<article class="review-card">${image(pos,`${name} in BLIU`)}<div class="review-copy"><p class="stars" aria-label="5 out of 5 stars">★★★★★</p><p>${quote}</p><span class="review-author">${name.toUpperCase()} · ${meta.toUpperCase()}</span></div></article>`).join('')}</div><p class="notice">These sample testimonials illustrate the layout and should be replaced with verified customer reviews before launch.</p></section>`;}
function activeLine(){const params=new URLSearchParams(location.search),requested=params.get('line');if(requested==='BLIU Luxe'||requested==='BLIU Essentials')return requested;const page=params.get('page');if(page==='home'||!page||page==='shop')return 'BLIU Essentials';if(page==='luxe')return 'BLIU Luxe';if(page==='essential')return 'BLIU Essentials';if(page==='product'){const p=products.find(x=>x.id===params.get('id'));if(p)return p.line;}if(page==='confirmation'){const order=readStore('bliu-last-order',null);if(order?.line)return order.line;}return readStore('bliu-active-line','BLIU Essentials');}
function compactSummary(total){return `<div class="summary-line"><span>Subtotal</span><span>${formatPrice(total)}</span></div><div class="summary-line"><span>Shipping</span><span>Complimentary</span></div><div class="summary-line"><span>Taxes</span><span>Included</span></div><div class="summary-line summary-total"><span>TOTAL</span><span>${formatPrice(total)}</span></div>`;}
function shoppingBagScreen(){const cart=getCart(),line=activeLine(),recommendations=products.filter(p=>p.line===line&&!cart.some(item=>item.id===p.id)).slice(0,4);if(!cart.length)return `<div class="page-heading"><p class="eyebrow">${line.toUpperCase()} · YOUR SELECTION</p><h1>Your bag is <em>empty.</em></h1><p class="detail-desc">Explore ${line} and save the pieces you love.</p></div><section class="bag-layout"><div class="empty-state"><h2>A little room for something special.</h2><p>Your bag is ready when you are.</p><a class="btn" href="?page=${line==='BLIU Luxe'?'luxe':'essential'}">CONTINUE SHOPPING ${line==='BLIU Luxe'?'LUXE':'ESSENTIALS'} ↗</a></div><aside class="order-summary"><h2>Order summary</h2>${compactSummary(0)}</aside></section>${recommendations.length?`<section class="section bag-recommendations"><div class="section-title"><div><p class="eyebrow">${line.toUpperCase()} ONLY</p><h2>Pieces to <em>discover.</em></h2></div><a class="underlink" href="?page=shop&line=${encodeURIComponent(line)}">SHOP THIS COLLECTION ↗</a></div><div class="product-grid">${recommendations.map(productCard).join('')}</div></section>`:''}`;let total=0;const rows=cart.map(item=>{const p=products.find(x=>x.id===item.id);if(!p)return '';total+=p.price*item.qty;return `<article class="cart-item"><a aria-label="View ${p.name}" href="?page=product&id=${p.id}">${image(p.position,p.name)}</a><div><p class="eyebrow">${p.line.toUpperCase()}</p><h3><a href="?page=product&id=${p.id}">${p.name}</a></h3><p>SIZE ${item.size||'M'} · ${p.color}</p><div class="cart-qty"><button type="button" data-qty="${p.id}" data-delta="-1" aria-label="Decrease quantity of ${p.name}">−</button><span>${item.qty}</span><button type="button" data-qty="${p.id}" data-delta="1" aria-label="Increase quantity of ${p.name}">+</button></div><button class="remove-item" type="button" data-remove="${p.id}">REMOVE</button></div><strong>${formatPrice(p.price*item.qty)}</strong></article>`}).join('');return `<div class="page-heading"><p class="eyebrow">${line.toUpperCase()} · YOUR SELECTION</p><h1>Shopping <em>bag.</em></h1><p class="detail-desc">Your selected pieces, together in one place.</p></div><section class="bag-layout"><div class="cart-list">${rows}<a class="underlink" href="?page=${line==='BLIU Luxe'?'luxe':'essential'}">← CONTINUE SHOPPING ${line==='BLIU Luxe'?'LUXE':'ESSENTIALS'}</a></div><aside class="order-summary"><h2>Order summary</h2>${compactSummary(total)}<form class="promo" data-form="promo"><label class="sr-only" for="promo-code">Promo code</label><input id="promo-code" placeholder="Promo code"><button class="btn small outline">APPLY</button></form><a class="btn" style="width:100%" href="?page=checkout&line=${encodeURIComponent(line)}">PROCEED TO CHECKOUT ↗</a><p class="notice">Need a fit recommendation? <a href="?page=contact">Speak with the BLIU Concierge.</a></p></aside></section>${recommendations.length?`<section class="section bag-recommendations"><div class="section-title"><div><p class="eyebrow">${line.toUpperCase()} ONLY</p><h2>Continue <em>exploring.</em></h2></div><a class="underlink" href="?page=shop&line=${encodeURIComponent(line)}">SHOP ALL ↗</a></div><div class="product-grid">${recommendations.map(productCard).join('')}</div></section>`:''}`;}
function checkoutScreen(){const cart=getCart(),line=activeLine(),total=cart.reduce((sum,item)=>{const p=products.find(x=>x.id===item.id);return sum+(p?p.price*item.qty:0)},0);return `<div class="page-heading"><p class="eyebrow">${line.toUpperCase()} · SECURE CHECKOUT</p><h1>Almost <em>yours.</em></h1><p class="detail-desc"><a href="?page=cart">Bag</a>　/　Delivery　/　Payment</p></div><section class="checkout-layout"><form class="form-panel checkout-form" data-form="checkout"><h2>Contact & delivery</h2><div class="field-grid"><div class="field full"><label for="checkout-email">EMAIL ADDRESS</label><input id="checkout-email" type="email" required autocomplete="email"></div><div class="field full"><label for="checkout-phone">MOBILE NUMBER</label><input id="checkout-phone" required type="tel" autocomplete="tel" placeholder="+91"></div><div class="field"><label for="first-name">FIRST NAME</label><input id="first-name" required autocomplete="given-name"></div><div class="field"><label for="last-name">LAST NAME</label><input id="last-name" required autocomplete="family-name"></div><div class="field full"><label for="street-address">ADDRESS</label><input id="street-address" required autocomplete="street-address"></div><div class="field"><label for="checkout-city">CITY</label><input id="checkout-city" required autocomplete="address-level2"></div><div class="field"><label for="checkout-state">STATE</label><input id="checkout-state" required autocomplete="address-level1"></div><div class="field"><label for="checkout-pin">PIN CODE</label><input id="checkout-pin" required inputmode="numeric" pattern="[0-9]{6}" autocomplete="postal-code" maxlength="6"></div></div><h2>Payment method</h2><div class="option-list"><label class="option-row"><input type="radio" name="payment" value="upi" checked> UPI</label><label class="option-row"><input type="radio" name="payment" value="card"> Credit or debit card</label><label class="option-row"><input type="radio" name="payment" value="netbanking"> Net banking</label><label class="option-row"><input type="radio" name="payment" value="cod"> Cash on delivery (where available)</label></div><p class="notice">Preview checkout only. No payment will be processed and your details are stored only in this browser.</p><button class="btn" style="margin-top:18px" ${cart.length?'':'disabled'}>PLACE PREVIEW ORDER · ${formatPrice(total)} ↗</button></form><aside class="order-summary checkout-summary"><h2>Your order</h2>${cart.length?cart.map(item=>{const p=products.find(x=>x.id===item.id);return p?`<div class="checkout-line"><div><span class="checkout-thumb">${image(p.position,p.name)}</span><div><p class="eyebrow">${p.line.toUpperCase()}</p><strong>${p.name}</strong><small>Size ${item.size||'M'} · Qty ${item.qty}</small></div></div><span>${formatPrice(p.price*item.qty)}</span></div>`:''}).join(''):'<div class="empty-state"><h2>Your bag is empty.</h2><a href="?page=essential">Continue shopping</a></div>'}${compactSummary(total)}<form class="promo" data-form="promo"><label class="sr-only" for="checkout-promo">Promo code</label><input id="checkout-promo" placeholder="Promo code"><button class="btn small outline">APPLY</button></form></aside></section>`;}
function orderConfirmationScreen(){const order=readStore('bliu-last-order',null);if(!order)return `<div class="page-heading"><p class="eyebrow">ORDER CONFIRMATION</p><h1>Nothing to <em>confirm yet.</em></h1></div><section class="section"><div class="empty-state"><h2>Your order summary will appear here.</h2><p>Place a preview order after adding a garment to your bag.</p><a class="btn" href="?page=essential">EXPLORE ESSENTIALS ↗</a></div></section>`;const line=order.line||'BLIU Essentials';return `<div class="confirmation-hero"><p class="eyebrow">ORDER ${order.id}</p><p class="confirmation-mark" aria-hidden="true">✓</p><h1>Thank you for choosing <em>BLIU.</em></h1><p>Your preview order is confirmed. No payment was taken.</p></div><section class="confirmation-grid"><article class="content-panel"><p class="eyebrow">NEXT STEPS</p><h2>We’ll keep you posted.</h2><p>A confirmation summary is saved in this browser preview. In a live store, this is where order updates would be sent.</p><a class="btn outline" href="?page=track&order=${encodeURIComponent(order.id)}">TRACK THIS ORDER ↗</a></article><aside class="order-summary"><p class="eyebrow">${line.toUpperCase()}</p><h2>Order summary</h2>${order.items.map(item=>{const p=products.find(x=>x.id===item.id);return p?`<div class="summary-line"><span>${p.name} · ${item.size} × ${item.qty}</span><span>${formatPrice(p.price*item.qty)}</span></div>`:''}).join('')}${compactSummary(order.total)}<p class="notice">Delivery details are held in the checkout session for this preview.</p></aside></section>`;}
function accountAccessScreen(){return `<div class="page-heading"><p class="eyebrow">YOUR BLIU · CLIENT ACCESS</p><h1>Welcome <em>back.</em></h1><p class="detail-desc">Sign in or create an account to keep your orders, saved addresses, and wishlist together.</p></div><section class="account-access-layout"><form class="form-panel" data-form="signin"><h2>Sign in or create account</h2><div class="field"><label for="client-name">YOUR NAME <span>(for a new account)</span></label><input id="client-name" name="name" autocomplete="name" placeholder="Name"></div><div class="field"><label for="client-contact">EMAIL OR MOBILE NUMBER</label><input id="client-contact" name="contact" required autocomplete="email" placeholder="you@example.com or +91"></div><p class="notice">This website preview stores account details only in your browser. Real sign-in requires an account service.</p><button class="btn">CONTINUE ↗</button></form><aside class="info-panel"><p class="eyebrow">A QUICKER WAY BACK</p><h2>Your BLIU, in one place.</h2><p>Keep track of clothing orders, save your fit preferences, and return to your favourite garments.</p><a class="underlink" href="?page=cart">CONTINUE AS GUEST · VIEW BAG ↗</a></aside></section>`;}
function accountDashboardScreen(){const client=readStore('bliu-client',null),order=readStore('bliu-last-order',null),line=activeLine(),address=readStore('bliu-address',null);return `<div class="page-heading"><p class="eyebrow">YOUR BLIU · ${line.toUpperCase()}</p><h1>Hello${client?.name?`, ${escapeText(client.name)}`:''}.</h1><p class="detail-desc">Your account, saved pieces, and recent orders.</p></div><section class="account-dashboard"><nav class="account-side" aria-label="Account navigation"><a class="active" href="?page=account">OVERVIEW</a><a href="?page=account#orders">ORDERS</a><a href="?page=account#addresses">ADDRESSES</a><a href="?page=wishlist&line=${encodeURIComponent(line)}">WISHLIST</a><a href="?page=size">SIZE & FIT</a><button class="account-signout" type="button" data-signout>SIGN OUT</button></nav><div class="account-main"><section class="content-panel"><p class="eyebrow">PROFILE</p><h2>${client?.contact?escapeText(client.contact):'Your details'}</h2><p>Manage your contact details and fit preferences with BLIU.</p><a class="underlink" href="?page=size">VIEW INDIAN SIZE GUIDE ↗</a></section><section class="content-panel" id="orders"><p class="eyebrow">RECENT ORDERS</p>${order?`<h2>${order.id}</h2><p>${order.items.length} garment${order.items.length===1?'':'s'} · ${formatPrice(order.total)} · Preview order</p><a class="btn outline small" href="?page=track&order=${encodeURIComponent(order.id)}">VIEW ORDER STATUS ↗</a>`:`<h2>No orders yet.</h2><p>Your order history will appear here.</p><a class="underlink" href="?page=${line==='BLIU Luxe'?'luxe':'essential'}">EXPLORE ${line.toUpperCase()} ↗</a>`}</section><section class="content-panel" id="addresses"><p class="eyebrow">SAVED ADDRESS</p><h2>${address?'Delivery address':'Add an address at checkout'}</h2><p>${address?escapeText(address):'Your delivery details can be saved when you place your next preview order.'}</p></section><section class="content-panel"><p class="eyebrow">FIT PROFILE</p><h2>Indian sizes, XS–XXL</h2><p>See the Indian size matrix and measurement guide before choosing a garment.</p><a class="underlink" href="?page=size">OPEN SIZE GUIDE ↗</a></section></div></section>`;}
function escapeText(value=''){return String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
function wishlistScreen(){const line=activeLine(),saved=getWishlist().map(id=>products.find(p=>p.id===id)).filter(p=>p&&p.line===line);return `<div class="page-heading"><p class="eyebrow">${line.toUpperCase()} · SAVED PIECES</p><h1>Your <em>wishlist.</em></h1><p class="detail-desc">Only ${line} garments appear in this collection wishlist.</p><div class="collection-tabs"><a class="${line==='BLIU Essentials'?'active':''}" href="?page=wishlist&line=BLIU%20Essentials">BLIU ESSENTIALS</a><a class="${line==='BLIU Luxe'?'active':''}" href="?page=wishlist&line=BLIU%20Luxe">BLIU LUXE</a></div></div><section class="catalog-section">${saved.length?`<div class="product-grid">${saved.map(productCard).join('')}</div>`:`<div class="empty-state"><h2>No saved garments here yet.</h2><p>Save pieces from ${line} while you browse.</p><a class="btn" href="?page=shop&line=${encodeURIComponent(line)}">EXPLORE ${line.toUpperCase()} ↗</a></div>`}</section>`;}
function shippingReturnsScreen(){return `<div class="page-heading"><p class="eyebrow">CLIENT CARE</p><h1>Shipping & <em>returns.</em></h1><p class="detail-desc">What to expect after you find the piece that feels like you.</p></div><section class="service-layout"><nav class="service-nav" aria-label="Shipping and returns sections"><a href="#delivery">DELIVERY</a><a href="#returns">RETURNS & EXCHANGES</a><a href="#refunds">REFUNDS</a><a href="#care">MADE-TO-ORDER & ALTERATIONS</a></nav><div class="service-copy"><article id="delivery"><p class="eyebrow">01 · DELIVERY</p><h2>From our studio to you.</h2><p>Delivery options and estimated timelines are shown at checkout for your address. You’ll receive an order update when your garment is dispatched. Keep your order reference handy to track its journey.</p></article><article id="returns"><p class="eyebrow">02 · RETURNS & EXCHANGES</p><h2>A little help with the fit?</h2><p>Return and exchange eligibility can vary by garment and order. Check the policy shown on the product page and at checkout before placing your order. For fit or alteration questions, contact the BLIU Concierge with your order reference.</p></article><article id="refunds"><p class="eyebrow">03 · REFUNDS</p><h2>Clear updates at every step.</h2><p>When a return is approved, refund timing depends on the original payment method and provider. The concierge can help with an existing request.</p></article><article id="care"><p class="eyebrow">04 · MADE-TO-ORDER & ALTERATIONS</p><h2>Made with care.</h2><p>Some BLIU Luxe garments may have a different preparation or alteration timeline. The product page will show garment-specific details; please contact us before ordering if you need help.</p></article><a class="btn" href="?page=contact">ASK THE CONCIERGE ↗</a></div></section>`;}
function conciergeScreen(){return `<div class="page-heading"><p class="eyebrow">BLIU CLIENT CARE</p><h1>Here to <em>help.</em></h1><p class="detail-desc">A personal point of contact for fit, styling, and order questions.</p></div><section class="concierge-layout"><form class="form-panel" data-form="contact"><h2>Send us a note</h2><div class="field-grid"><div class="field"><label for="contact-name">NAME</label><input id="contact-name" name="name" required autocomplete="name"></div><div class="field"><label for="contact-email">EMAIL</label><input id="contact-email" name="email" type="email" required autocomplete="email"></div><div class="field"><label for="contact-phone">PHONE (OPTIONAL)</label><input id="contact-phone" name="phone" type="tel" autocomplete="tel"></div><div class="field"><label for="contact-topic">WHAT CAN WE HELP WITH?</label><select id="contact-topic" name="topic"><option>Fit and sizing</option><option>Styling advice</option><option>Order support</option><option>Something else</option></select></div><div class="field full"><label for="contact-order">ORDER NUMBER (OPTIONAL)</label><input id="contact-order" name="order"></div><div class="field full"><label for="contact-message">MESSAGE</label><textarea id="contact-message" name="message" required></textarea></div></div><button class="btn">SEND MESSAGE ↗</button><p class="notice" id="contact-status" aria-live="polite">This preview does not send or save your message.</p></form><aside class="info-panel"><p class="eyebrow">PERSONAL ASSISTANCE</p><h2>Need a hand choosing?</h2><p>Our concierge can help you compare silhouettes, check the Indian size guide, or find the right BLIU collection.</p><a class="btn outline" href="?page=size">OPEN SIZE GUIDE ↗</a><div class="concierge-links"><a href="?page=faq">FREQUENTLY ASKED QUESTIONS ↗</a><a href="?page=shipping">SHIPPING & RETURNS ↗</a><a href="?page=track">TRACK AN ORDER ↗</a></div></aside></section>`;}
function faqScreen(){const groups=[['Orders & payments',[['How do I place an order?','Choose a garment, select your size, add it to your bag, and follow the checkout steps. The current site is a front-end preview and does not process payments.'],['Which payment methods are available?','The checkout preview shows UPI, cards, net banking, and cash on delivery where available. A live store will show the payment methods configured for your order.'],['Can I change my order?','Contact the BLIU Concierge as soon as possible with your order number. Changes depend on the garment’s preparation status.']]],['Indian sizing & fit',[['How do I choose my size?','Use the Indian size matrix on the Size Guide page. For a garment-specific fit question, contact the BLIU Concierge.'],['Where can I find garment measurements?','Open the size guide from any product page. Product-specific measurements and ease should be confirmed for each garment before launch.']]],['Shipping, returns & garment care',[['When will my garment arrive?','Delivery options and estimated timing are shown for your address during checkout. Follow the order tracking page for updates.'],['Can I return or exchange a garment?','Eligibility varies by garment. Review the policy shown on its product page and at checkout, or ask the Concierge before ordering.'],['How should I care for my garment?','Follow the care instructions provided with the garment. If you are unsure about a fabric or finish, ask the Concierge.']]],['Account & saved pieces',[['How do I save a garment?','Use the heart on a product card to add it to your collection-specific wishlist.'],['How do I view my order?','Sign in to view recent preview orders, or use Track Order with your order reference.']]]];return `<div class="page-heading"><p class="eyebrow">CLIENT CARE</p><h1>Questions, <em>answered.</em></h1><p class="detail-desc">Browse helpful details about orders, fit, and caring for your BLIU garments.</p></div><section class="faq-layout"><nav class="faq-cats" aria-label="FAQ topics"><a href="#orders">ORDERS & PAYMENTS ↗</a><a href="#fit">INDIAN SIZING & FIT ↗</a><a href="#delivery">SHIPPING & RETURNS ↗</a><a href="#account-help">ACCOUNT ↗</a><a href="?page=size">SIZE GUIDE ↗</a></nav><div class="faq-list">${groups.map(([title,items],i)=>`<section id="${['orders','fit','delivery','account-help'][i]}" class="faq-group"><h2>${title}</h2>${items.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section>`).join('')}<div class="content-panel"><h2>Still need a hand?</h2><a class="btn" href="?page=contact">CONTACT THE CONCIERGE ↗</a></div></div></section>`;}
function trackOrderScreen(){const order=readStore('bliu-last-order',null);return `<div class="page-heading"><p class="eyebrow">YOUR ORDER, IN VIEW</p><h1>Track your <em>order.</em></h1><p class="detail-desc">Enter the reference from your order confirmation to see the current preview status.</p></div><section class="two-column"><form class="form-panel" data-form="track"><h2>Order status lookup</h2><div class="field"><label for="order-reference">ORDER REFERENCE</label><input id="order-reference" required name="order" value="${escapeText(new URLSearchParams(location.search).get('order')||'')}" placeholder="e.g. ${order?escapeText(order.id):'BLIU-2026-000001'}"></div><button class="btn">LOOK UP ORDER ↗</button><div id="track-result" aria-live="polite"></div></form><div class="info-panel"><p class="eyebrow">NEED A HAND?</p><h2>We’re here to help.</h2><p>For a personal order update, contact the Concierge with your order reference.</p><a class="btn outline" href="?page=contact">CONTACT THE CONCIERGE ↗</a></div></section>`;}
function getPageContent(page,id){switch(page){case'shop':return shop();case'luxe':return collection('luxe');case'essential':return collection('essential');case'product':return productDetail(id);case'cart':return shoppingBagScreen();case'checkout':return checkoutScreen();case'confirmation':return orderConfirmationScreen();case'signin':return accountAccessScreen();case'account':return accountDashboardScreen();case'wishlist':return wishlistScreen();case'shipping':return shippingReturnsScreen();case'contact':return conciergeScreen();case'story':return story();case'size':return sizeGuide();case'faq':return faqScreen();case'track':return trackOrderScreen();case'journal':return journal();case'reviews':return reviews();default:return home();}}
function setupMotion(){if(window.matchMedia('(prefers-reduced-motion: reduce)').matches||!('IntersectionObserver'in window))return;const targets=document.querySelectorAll('.gateway-intro,.gateway-choice .line-choice-card,.gateway-story,.essential-home-copy,.hero-content,.category-tile,.product-card,.craft-detail-grid article,.editorial-copy,.feature-ribbon>div');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('motion-visible');observer.unobserve(entry.target)}}),{threshold:.08,rootMargin:'0px 0px -24px 0px'});targets.forEach((item,index)=>{item.classList.add('motion-item');item.style.setProperty('--motion-order',String(index%5));observer.observe(item)});}
function render(){const {page,id}=getRoute(),params=new URLSearchParams(location.search),product=products.find(p=>p.id===id),line=activeLine(),luxe=line==='BLIU Luxe';if(page==='luxe'||page==='essential'||page==='shop'||page==='product')writeStore('bliu-active-line',line);document.body.className=luxe?'dark theme-luxe':'theme-essential';const themeColor=document.querySelector('meta[name="theme-color"]');if(themeColor)themeColor.content=luxe?'#0A0A0A':'#FAF9F5';const root=document.getElementById('app');root.innerHTML=header(luxe?'luxe':'essential')+`<main>${getPageContent(page,id)}</main>`+footer()+`<div class="toast" role="status" aria-live="polite"></div>`;root.querySelectorAll('.product-card').forEach(card=>{const button=document.createElement('button');button.className='wish-toggle';button.type='button';button.dataset.wish=card.dataset.product;button.setAttribute('aria-label','Save to wishlist');button.textContent=getWishlist().includes(card.dataset.product)?'♥':'♡';card.querySelector('.product-picture')?.after(button)});document.title=`${pageNames[page]||'BLIU'} — BLIU`;if(page==='shop')setupFilters();if(page==='product')setupGallery();setupMotion();}
function toast(message){const el=document.querySelector('.toast');if(!el)return;el.textContent=message;el.classList.add('show');window.clearTimeout(toast.timeout);toast.timeout=window.setTimeout(()=>el.classList.remove('show'),2400);}
function addToCart(id){const size=document.querySelector('.size-option.selected')?.dataset.size||'M';const cart=getCart();const found=cart.find(x=>x.id===id&&x.size===size);if(found)found.qty++;else cart.push({id,size,qty:1});writeStore('bliu-cart',cart);const count=document.querySelector('.bag-trigger b');if(count)count.textContent=getCart().reduce((n,item)=>n+item.qty,0);toast('Added to your bag.');}
function setupFilters(){const grid=document.getElementById('catalog-grid');if(!grid)return;const cards=[...grid.children],params=new URLSearchParams(location.search),category=document.getElementById('category-filter'),drawer=document.getElementById('filter-drawer'),toggle=document.querySelector('.filter-open');if(category&&params.has('category'))category.value=params.get('category');const filter=()=>{const cat=category?.value||'all',fabric=document.getElementById('fabric-filter')?.value||'all',color=document.getElementById('color-filter')?.value||'all',craft=document.getElementById('craft-filter')?.value||'all',size=document.getElementById('size-filter')?.value||'all',sort=document.getElementById('sort-filter')?.value||'featured';let shown=cards.filter(card=>(cat==='all'||card.dataset.category===cat)&&(fabric==='all'||card.dataset.fabric===fabric)&&(color==='all'||card.dataset.color===color)&&(craft==='all'||card.dataset.craft===craft)&&(size==='all'||card.dataset.sizes.includes(size)));shown.sort((a,b)=>sort==='low'?+a.dataset.price-+b.dataset.price:sort==='high'?+b.dataset.price-+a.dataset.price:cards.indexOf(a)-cards.indexOf(b));cards.forEach(c=>c.remove());shown.forEach(c=>grid.append(c));document.getElementById('result-count').textContent=`${String(shown.length).padStart(2,'0')} PIECES · ${params.get('line')||'BLIU Essentials'}`;};document.querySelectorAll('#filter-drawer select,#sort-filter').forEach(s=>s.addEventListener('change',filter));toggle?.addEventListener('click',()=>{drawer.hidden=false;toggle.setAttribute('aria-expanded','true')});document.querySelector('.filter-close')?.addEventListener('click',()=>{drawer.hidden=true;toggle?.setAttribute('aria-expanded','false')});document.querySelector('.filter-apply')?.addEventListener('click',()=>{drawer.hidden=true;toggle?.setAttribute('aria-expanded','false');filter()});filter();}
function setupGallery(){document.querySelectorAll('.gallery-thumb').forEach(thumb=>thumb.addEventListener('click',()=>{document.querySelector('.gallery-thumb.selected')?.classList.remove('selected');thumb.classList.add('selected');const main=document.querySelector('.gallery-main');const view=thumb.dataset.view||'full';main.innerHTML=image(+thumb.dataset.position,'Product view of the selected garment',view==='full'?'gallery-full':`gallery-zoom-${view}`);}));}
document.addEventListener('click',event=>{const signout=event.target.closest('[data-signout]');if(signout){localStorage.removeItem('bliu-client');location.href='?page=signin';return;}const wish=event.target.closest('[data-wish]');if(wish){event.preventDefault();event.stopPropagation();const id=wish.dataset.wish,list=getWishlist();const next=list.includes(id)?list.filter(x=>x!==id):[...list,id];writeStore('bliu-wishlist',next);wish.textContent=next.includes(id)?'♥':'♡';toast(next.includes(id)?'Saved to your wishlist.':'Removed from wishlist.');return;}const size=event.target.closest('.size-option');if(size){document.querySelector('.size-option.selected')?.classList.remove('selected');size.classList.add('selected');return;}const add=event.target.closest('[data-add]');if(add){addToCart(add.dataset.add);return;}const rm=event.target.closest('[data-remove]');if(rm){writeStore('bliu-cart',getCart().filter(item=>item.id!==rm.dataset.remove));render();return;}const qty=event.target.closest('[data-qty]');if(qty){const delta=+qty.dataset.delta;const cart=getCart();const item=cart.find(x=>x.id===qty.dataset.qty);if(item)item.qty+=delta;writeStore('bliu-cart',cart.filter(x=>x.qty>0));render();return;}const menu=event.target.closest('.mobile-menu');if(menu){const nav=document.querySelector('.main-nav');const opened=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(opened));menu.setAttribute('aria-label',opened?'Close navigation':'Open navigation');}});
document.addEventListener('submit',event=>{const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();if(form.dataset.form==='newsletter'){toast('You’re on the list. Welcome to BLIU.');form.reset();}if(form.dataset.form==='checkout'){const data=new FormData(form),cart=getCart(),total=cart.reduce((sum,item)=>{const p=products.find(x=>x.id===item.id);return sum+(p?p.price*item.qty:0)},0),id=`BLIU-${new Date().getFullYear()}-${String(Date.now()).slice(-6)}`;writeStore('bliu-last-order',{id,line:activeLine(),items:cart,total,createdAt:new Date().toISOString()});writeStore('bliu-client',{name:data.get('first-name'),contact:data.get('checkout-email')});writeStore('bliu-address',[data.get('street-address'),data.get('checkout-city'),data.get('checkout-state'),data.get('checkout-pin')].filter(Boolean).join(', '));writeStore('bliu-cart',[]);location.href=`?page=confirmation&line=${encodeURIComponent(activeLine())}`;}if(form.dataset.form==='signin'){const data=new FormData(form);writeStore('bliu-client',{name:data.get('name')||'',contact:data.get('contact')});location.href=`?page=account&line=${encodeURIComponent(activeLine())}`;}if(form.dataset.form==='contact'){const status=document.getElementById('contact-status');if(status)status.textContent='Thanks for reaching out. This preview does not transmit your message; connect a form service to receive enquiries.';form.reset();}if(form.dataset.form==='promo'){toast('Promo codes will be available when the store launches.');}if(form.dataset.form==='track'){const code=new FormData(form).get('order').trim().toUpperCase(),order=readStore('bliu-last-order',null),result=document.getElementById('track-result'),found=order&&code===order.id.toUpperCase();result.innerHTML=found?'<div class="status-steps"><div class="status-step done"><i></i>CONFIRMED</div><div class="status-step done"><i></i>PREPARING</div><div class="status-step"><i></i>SHIPPED</div><div class="status-step"><i></i>DELIVERED</div></div><p class="notice">Preview status: this order has been received and is being prepared.</p>':'<p class="notice">No preview order was found for that reference. Please check the code or message our concierge.</p>';}});
document.addEventListener('click',event=>{const control=event.target.closest('[data-category-scroll]');if(!control)return;const rail=control.closest('.category-section')?.querySelector('.category-grid');if(rail)rail.scrollBy({left:Number(control.dataset.categoryScroll)*rail.clientWidth*.78,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});});
window.addEventListener('storage',render);
render();
